from typing import List, Tuple

# This generator crafts valid JSON documents tailored to exercise:
# - json_walk: variety of token types, nested objects/arrays, different key forms
# - json_scanf: fields b (bool), s (string), v (base64 blob), h (hex), t (any token)
# - json_prettify: compact input to pretty-printer
# The output is a bytes buffer of a JSON document (<= 4096 bytes).

HEX_ALPHABET = "0123456789abcdef"


def _rand(r: random.Random, seq):
    return seq[r.randrange(0, len(seq))]


def rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    # Mix of visible ASCII plus some escapes candidates
    letters = string.ascii_letters + string.digits + " _-./:@[]{}()!?$#,+*\t\n\r"
    n = r.randint(min_len, max_len)
    s = "".join(_rand(r, letters) for _ in range(n))
    # Occasionally insert quotes and backslashes that require escaping
    if n > 0 and r.random() < 0.4:
        pos = r.randrange(0, n)
        insert = '"' if r.random() < 0.5 else "\\"
        s = s[:pos] + insert + s[pos:]
    return s


def make_base64_blob(r: random.Random, min_len=0, max_len=64) -> Tuple[str, bytes]:
    raw_len = r.randint(min_len, max_len)
    raw = bytes(r.getrandbits(8) for _ in range(raw_len))
    b64 = base64.b64encode(raw).decode("ascii")
    return b64, raw


def make_hex_blob(r: random.Random, min_len=0, max_len=64) -> Tuple[str, bytes]:
    raw_len = r.randint(min_len, max_len)
    raw = bytes(r.getrandbits(8) for _ in range(raw_len))
    hx = "".join(f"{b:02x}" for b in raw)
    return hx, raw


def make_number(r: random.Random):
    # Integers and floats, including edge-like values
    choices = [
        0, 1, -1, 2**31 - 1, -2**31, 2**63 - 1, -2**63 + 1,
        r.randint(-10**9, 10**9),
        round(r.uniform(-1e6, 1e6), r.randint(0, 6)),
    ]
    return _rand(r, choices)


def make_array(r: random.Random, depth: int) -> list:
    n = r.randint(0, 8)
    arr = []
    for _ in range(n):
        arr.append(make_value(r, depth + 1))
    return arr


def make_object(r: random.Random, depth: int) -> dict:
    m = {}
    # Use various key styles to test mg_match_prefix-ish paths, case, etc.
    key_bases = [
        "a", "A", "alpha", "ALPHA", "_k", "k-1", "k_2", "path/like", "with space",
        "unicode", "num123", "json", "x", "y", "z"
    ]
    n = r.randint(1, 8)
    for _ in range(n):
        key = _rand(r, key_bases) + ("_" + str(r.randint(0, 3)) if r.random() < 0.5 else "")
        # ensure unique keys
        while key in m:
            key += str(r.randint(0, 9))
        m[key] = make_value(r, depth + 1)
    return m


def make_value(r: random.Random, depth: int):
    # Limit depth to avoid deep recursion
    if depth > 4:
        kind = _rand(r, ["string", "number", "bool", "null"])
    else:
        kind = _rand(r, ["string", "number", "bool", "null", "array", "object"])
    if kind == "string":
        return rand_ascii(r, 0, 24)
    if kind == "number":
        return make_number(r)
    if kind == "bool":
        return bool(r.getrandbits(1))
    if kind == "null":
        return None
    if kind == "array":
        return make_array(r, depth)
    if kind == "object":
        return make_object(r, depth)


def build_root_for_scanf(r: random.Random) -> dict:
    # Ensure fields expected by json_scanf fuzzer exist and are valid:
    # b (bool), s (string), v (base64), h (hex), t (any token)
    b = bool(r.getrandbits(1))
    s = rand_ascii(r, 0, 40)
    v_b64, _ = make_base64_blob(r, 0, 48)
    h_hex, _ = make_hex_blob(r, 0, 48)

    # t can be any token; choose one of several interesting types
    t_val = make_value(r, 0)

    root = {
        "b": b,
        "s": s,
        "v": v_b64,
        "h": h_hex,
        # Include an array as in the stub building input, with extra elements
        "arr": [1, 2, 3, r.randint(-5, 5)],
        # Extra content to exercise walker and prettifier
        "nested": {
            "empty_obj": {},
            "empty_arr": [],
            "deep": {
                "t": t_val,
                "nums": [make_number(r) for _ in range(r.randint(0, 5))],
            },
        },
    }

    # Add some sibling fields of varied types to broaden token coverage
    root.update({
        "nullish": None,
        "truthy": True,
        "falsy": False,
        "str2": rand_ascii(r, 0, 24),
        "obj": make_object(r, 0),
        "arr2": make_array(r, 0),
    })
    return root


def maybe_minify(json_text: str, r: random.Random) -> str:
    # The fuzzers accept any valid JSON; provide compact form mostly
    if r.random() < 0.8:
        return json_text  # json.dumps is already compact by default when separators default
    else:
        # Pretty then strip some whitespaces to create variants
        pretty = json.dumps(json.loads(json_text), indent=2, ensure_ascii=False)
        # Randomly remove some newlines/spaces to produce semi-compact
        lines = pretty.splitlines()
        if not lines:
            return pretty
        kept = []
        for ln in lines:
            if r.random() < 0.3:
                kept.append(ln.strip())
            else:
                kept.append(ln)
        return "\n".join(kept)


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Build a root object specifically covering json_scanf fields plus extras
    root = build_root_for_scanf(r)

    # Randomly wrap into a top-level array/object mixture to diversify json_walk
    wrap_choice = r.random()
    if wrap_choice < 0.2:
        # Plain object (as is)
        top = root
    elif wrap_choice < 0.55:
        # Array with the object placed among other values
        prefix_vals = [make_value(r, 0) for _ in range(r.randint(0, 3))]
        suffix_vals = [make_value(r, 0) for _ in range(r.randint(0, 3))]
        top = prefix_vals + [root] + suffix_vals
    else:
        # Object with multiple fields including the root under a key
        top = {
            "payload": root,
            "meta": {
                "id": rand_ascii(r, 3, 12),
                "ver": r.randint(0, 5),
            },
            "list": make_array(r, 0),
        }

    # Dump JSON ensuring valid UTF-8; ensure within size budget
    text = json.dumps(top, separators=(",", ":"), ensure_ascii=False)
    text = maybe_minify(text, r)

    # If too large, iteratively prune optional parts
    max_len = 4096
    if len(text.encode("utf-8")) > max_len:
        # Simplify arrays/objects deterministically using RNG to select removals
        def shrink(obj):
            if isinstance(obj, list):
                while obj and len(json.dumps(top, separators=(",", ":"), ensure_ascii=False).encode("utf-8")) > max_len:
                    obj.pop()
            elif isinstance(obj, dict):
                keys = list(obj.keys())
                while keys and len(json.dumps(top, separators=(",", ":"), ensure_ascii=False).encode("utf-8")) > max_len:
                    k = keys.pop()
                    # Keep required fields for scanf when at root
                    if obj is root and k in ("b", "s", "v", "h", "arr", "nested"):
                        continue
                    obj.pop(k, None)
            return obj
        # Try shrinking several parts
        if isinstance(top, dict):
            shrink(top)
            if "payload" in top and isinstance(top["payload"], dict):
                shrink(top["payload"])  # type: ignore
        if isinstance(top, list):
            shrink(top)
        # Re-emit
        text = json.dumps(top, separators=(",", ":"), ensure_ascii=False)

    # Final guard
    b = text.encode("utf-8")
    if len(b) > max_len:
        b = b[:max_len]
    return b

import random
import string
from typing import List

# Target: Generate bytes suitable for FUZZ_PARAM_STR and FUZZ_PARAM_FILENAME
# Covers JSON %Q/%.*Q (arbitrary text, with quotes/backslashes/controls),
# %V (arbitrary binary), %H (mostly valid hex, sometimes odd/invalid), and a filename.
# We pack entries as NUL-terminated chunks in this order: [filename, q, qn, v, h].
# Keep total size <= 4096 bytes.

MAX_TOTAL = 4096

_HEX_CHARS_LOWER = b"0123456789abcdef"
_HEX_CHARS_UPPER = b"0123456789ABCDEF"


def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    pool = string.ascii_letters + string.digits + string.punctuation + " \t\r\n"
    s = ''.join(rng.choice(pool) for _ in range(n))
    return s.encode('utf-8', 'ignore')


def _rand_utf8(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    out = bytearray()
    while len(out) < n:
        choice = rng.random()
        if choice < 0.6:
            out.append(rng.randrange(0x20, 0x7F))  # printable ASCII
        elif choice < 0.75:
            cp = rng.randrange(0x80, 0x800)
            out += chr(cp).encode('utf-8')
        elif choice < 0.9:
            cp = rng.randrange(0x800, 0xD800)
            out += chr(cp).encode('utf-8')
        else:
            cp = rng.randrange(0x10000, 0x10FFFF)
            out += chr(cp).encode('utf-8')
    return bytes(out[:n])


def _with_controls_quotes(rng: random.Random, base: bytes) -> bytes:
    inserts = [b'"', b"\\", b"\b", b"\f", b"\n", b"\r", b"\t"]
    data = bytearray(base)
    for ins in inserts:
        pos = rng.randrange(0, len(data) + 1) if data else 0
        data[pos:pos] = ins
        if len(data) > 512:
            break
    return bytes(data)


def _rand_binary(rng: random.Random, min_len: int, max_len: int) -> bytes:
    n = rng.randint(min_len, max_len)
    return bytes(rng.getrandbits(8) for _ in range(n))


def _rand_hex_string(rng: random.Random, valid_bias: float = 0.8) -> bytes:
    # Mostly valid even-length hex, sometimes odd or invalid
    mode = rng.random()
    if mode < valid_bias:
        # valid hex, even length 0..512
        length = rng.choice([0, 2, 4, 6, 8, 16, 32, 64, 128, rng.randrange(2, 514, 2)])
        chars = rng.choice([_HEX_CHARS_LOWER, _HEX_CHARS_UPPER])
        return bytes(rng.choice(chars) for _ in range(length))
    elif mode < 0.9:
        # odd length valid hex
        odd_lengths = [1, 3, 5, 7, 9, 11, 13, 15]
        length = rng.choice(odd_lengths)
        chars = rng.choice([_HEX_CHARS_LOWER, _HEX_CHARS_UPPER])
        return bytes(rng.choice(chars) for _ in range(length))
    else:
        # include non-hex characters
        length = rng.randint(1, 128)
        pool = (_HEX_CHARS_LOWER + _HEX_CHARS_UPPER + b"xz-:_/ !@#\n\r")
        return bytes(rng.choice(pool) for _ in range(length))


def _rand_filename(rng: random.Random) -> bytes:
    base_names = [
        "out.json", "data.txt", "test.log", "a", "b", "file", "result.bin",
        "unicode_\u2713.json", "spaced name.txt", ".hidden", "numbers_123.json"
    ]
    if rng.random() < 0.5:
        name = rng.choice(base_names)
    else:
        parts: List[str] = []
        depth = 0 if rng.random() < 0.7 else rng.randint(1, 3)
        for _ in range(depth):
            seg = ''.join(rng.choice(string.ascii_letters + string.digits + "-_") for _ in range(rng.randint(1, 8)))
            parts.append(seg)
        stem = ''.join(rng.choice(string.ascii_letters + string.digits + "-_ ") for _ in range(rng.randint(1, 10))).strip()
        if not stem:
            stem = "f"
        ext = rng.choice([".json", ".txt", ".log", ".bin", ""])
        parts.append(stem + ext)
        name = "/".join(parts)
    name = name.lstrip("/")
    if not name:
        name = "out.json"
    return name.encode('utf-8', 'ignore')


def _pack_null_terminated(chunks: List[bytes]) -> bytes:
    out = bytearray()
    for c in chunks:
        c = c.replace(b"\x00", b"")
        if len(out) + len(c) + 1 > MAX_TOTAL:
            c = c[: max(0, MAX_TOTAL - len(out) - 1)]
        out += c
        out += b"\x00"
        if len(out) >= MAX_TOTAL:
            break
    return bytes(out[:MAX_TOTAL])


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # q: rich UTF-8 with controls/quotes
    q_base = _rand_utf8(rng, 0, 200)
    q = _with_controls_quotes(rng, q_base) if rng.random() < 0.9 else q_base

    # qn: length-controlled string; include empty, ascii, and longer utf-8 variants
    p = rng.random()
    if p < 0.3:
        qn = b""
    elif p < 0.6:
        qn = _rand_ascii(rng, 1, 64)
    else:
        qn = _rand_utf8(rng, 50, 300)

    # v: arbitrary binary incl. NULs
    v = _rand_binary(rng, 0, 256)

    # h: mostly valid hex, sometimes odd/invalid
    h = _rand_hex_string(rng, valid_bias=0.85)

    # filename
    fname = _rand_filename(rng)

    chunks = [fname, q, qn, v, h]
    return _pack_null_terminated(chunks)
